"""Add a parrot chasing the sea serpent to the SVGs generated by Platane/snk.

Usage: python parrot_chase.py dist/sea-serpent.svg dist/sea-serpent-dark.svg

The parrot reuses the snake head's own animation (keyframes "s0"), started a little
later, so it follows the snake's exact path just behind it, and dives at it now and then.
"""

import re
import sys
from pathlib import Path

from parrot import parrot, parrot_css

LAG_MS = 900        # how far behind the snake's head the parrot flies
HEADROOM = 44       # extra space added above the grid for the parrot
SIZE = 30


def add_parrot(svg):
    duration = int(re.search(r"\.s\{[^}]*?(\d+)ms", svg).group(1))

    # Make room above the contribution grid
    def grow(match):
        min_x, min_y, width, height = (float(v) for v in match.group(1).split())
        return f'viewBox="{min_x:g} {min_y - HEADROOM:g} {width:g} {height + HEADROOM:g}"'

    svg = re.sub(r'viewBox="([^"]+)"', grow, svg, count=1)
    svg = re.sub(r'(<svg[^>]*?\sheight=")(\d+(?:\.\d+)?)(")', lambda m: f"{m.group(1)}{float(m.group(2)) + HEADROOM:g}{m.group(3)}", svg, count=1)

    css = (
        parrot_css("ch", flap="0.16s", wing_angle=32, talk=False, bob=False)
        + f"\n.chase {{ animation: s0 {duration}ms linear infinite; animation-delay: -{duration - LAG_MS}ms; }}"
        + "\n.dive { animation: dive 4.5s ease-in-out infinite; }"
        + "\n@keyframes dive { 0%, 70%, 100% { transform: translate(0, 0); } 35% { transform: translate(0, -5px); }"
          " 80% { transform: translate(6px, 20px) rotate(18deg); } 86% { transform: translate(0, 0); } }"
    )
    bird = (
        f'<g class="chase"><g class="dive">'
        f'{parrot("ch", -SIZE * 0.35, -SIZE - 10, SIZE, face_right=True, feet=False)}'
        f"</g></g>"
    )
    svg = svg.replace("</style>", css + "</style>", 1)
    return svg.replace("</svg>", bird + "</svg>")


def main(paths):
    for path in paths:
        file = Path(path)
        file.write_text(add_parrot(file.read_text(encoding="utf-8")), encoding="utf-8")
        print(f"🦜 parrot added to {file}")


if __name__ == "__main__":
    main(sys.argv[1:])
